        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: openFormList (인자 미해석) · openFormList (인자 미해석) · fn_viewOtherForm (인자 미해석) · document.getElementById('${formList.formCd}'+'_0_otherForm').style.display = 'none'; (EL 미해석) */
        await scwin.goWrite(r["formCd"], r["beforeFormVer"], r["engFormCd"], r["beforeEngFormVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "1", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"], r["formWrtMethdTpCd"], r["exmptObjDisclsYn"], r["engMandatory1Yn"], r["eqtyoptIsuObjFormYn"]); return;
