 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_formPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_formPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_viewOtherForm (인자 미해석) · document.getElementById('${form.formCd}'+'_0_1_otherForm').style.display = 'none'; (EL 미해석) */
        if (r["oldFormVerUseYn"] === 'Y') { await scwin.goWrite(r["formCd"], r["beforeFormVer"], r["engFormCd"], r["beforeEngFormVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "1", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"], r["formWrtMethdTpCd"], r["exmptObjDisclsYn"], r["engMandatory1Yn"], r["eqtyoptIsuObjFormYn"]); return; }
        if (r["oldFormVerUseYn"] === 'Y') { await scwin.goWrite(r["formCd"], r["formVer"], r["engFormCd"], r["engFormVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "1", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"], r["formWrtMethdTpCd"], r["exmptObjDisclsYn"], r["engMandatory1Yn"], r["eqtyoptIsuObjFormYn"]); return; }
        if (r["engFormYn"] === 'Y') { await scwin.goWrite(r["formCd"], r["formVer"], r["engFormCd"], r["engFormVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "1", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"], r["formWrtMethdTpCd"], r["exmptObjDisclsYn"], r["engMandatory1Yn"], r["eqtyoptIsuObjFormYn"]); return; }
        if (r["engFormYn"] === 'Y') { await scwin.disclosurePreview(r["formCd"], r["engFormVer"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formPageList.oncellclick' });
    }
};

