/**
 * @method
 * @name viewFormList
 * @description view Form List 처리
 * @returns {void}
 * @hidden N
 */
scwin.viewFormList = function () {
    let all_checked = true;
    for (let i = 0; i < $c.util.getComponent('ipt_editClass').length; i++) {
        if ($c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue() === "TEMP") {
            continue;
        }
        const prefix = $c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue();
        if ((String($c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue() || '') !== '')) {
            scwin.displaySubEditList(prefix, "block");
        } else {
            all_checked = false;
            scwin.displaySubEditList(prefix, "none");
        }
    }
    $c.util.getComponent("ipt_allEdit").setValue(all_checked);
};

/**
 * @method
 * @name displaySubEditList
 * @description display Sub Edit List 처리
 * @param {*} prefix prefix
 * @param {*} _display _display
 * @returns {void}
 * @hidden N
 */
scwin.displaySubEditList = function (prefix, _display) {
    const subobj = document.all["subEditClass_" + prefix];
    for (let i = 0; i < subobj.length; i++) {
        subobj[i].style.display = _display;
    }
};

/**
 * @method
 * @name viewAllFormList
 * @description view All Form List 처리
 * @returns {void}
 * @hidden N
 */
scwin.viewAllFormList = function () {
    for (let i = 0; i < $c.util.getComponent('ipt_editClass').length; i++) {
        $c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).checked = (String($c.util.getComponent('ipt_allEdit').getValue() || "") !== "");
    }
    scwin.viewFormList();
};

/**
 * @method
 * @name openFormList
 * @description open Form List 처리
 * @param {*} subobj subobj
 * @param {*} listseq listseq
 * @returns {void}
 * @hidden N
 */
scwin.openFormList = function (subobj, listseq) {
    const formDiv = document.all["formList_" + listseq];
    const blankDiv = document.all["blankList_" + listseq];
    if (formDiv.style.display === "block") {
        subobj.src = "/img/submission/main/open_folder.gif";
        formDiv.style.display = "none";
        blankDiv.style.display = "block";
    } else {
        subobj.src = "/img/submission/main/close_folder.gif";
        formDiv.style.display = "block";
        blankDiv.style.display = "none";
    }
};

/**
 * @method
 * @name searchDisclosureForm
 * @description search Disclosure Form 처리
 * @param {*} searchScope searchScope
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDisclosureForm = async function (searchScope) {
    $c.util.getComponent('dma_searchDisclosureFormReq').set('searchScope', searchScope);
    $c.util.getComponent('dma_searchDisclosureFormReq').set('isAllEdit', "false");
    if (searchScope === 1) {
        if (($c.util.getComponent('ipt_formKorNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_formKorNm1').getValue())) === '') {
            await $c.win.alert('검색어를 입력 하세요');
            return;
        }
        for (let i = 0; i < $c.util.getComponent('ipt_editClass').length; i++) {
            if ((String($c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue() || '') !== '')) {
                break;
            }
            if (i === $c.util.getComponent('ipt_editClass').length - 1) {
                (String($c.util.getComponent('ipt_allEdit').getValue() || "") !== "");
                $c.util.getComponent('dma_searchDisclosureFormReq').set('isAllEdit', "true");
            }
        }
    } else {
        if (($c.util.getComponent('ipt_formKorNm2').getValue() == null ? '' : String($c.util.getComponent('ipt_formKorNm2').getValue())) === '') {
            await $c.win.alert('검색어를 입력 하세요');
            return;
        }
    }
    if ((String($c.util.getComponent('ipt_allEdit').getValue() || "") !== "") || searchScope === 2) {
        $c.util.getComponent('dma_searchDisclosureFormReq').set('isAllEdit', "true");
    }
    $c.util.getComponent('dma_searchDisclosureFormReq').set('formKorNm', $c.str.trim($c.util.getComponent("ipt_formKorNm" + searchScope).getValue()));
    $c.util.getComponent('dma_searchDisclosureFormReq').set('tabDiv', "search");
    $c.util.getComponent('dma_searchDisclosureFormReq').set('method', "searchDisclosureForm");
    editForm.action = "/submission/searchDisclosureForm.do";
    await scwin.tx_searchDisclosureForm();
};

